class Solution:
    def isNStraightHand(self, hand: List[int], groupSize: int) -> bool:
        if len(hand) % groupSize:
            return False
        count = Counter(hand)
        for value in sorted(count):
            need = count[value]
            if need == 0:
                continue  # already consumed by earlier groups
            for v in range(value, value + groupSize):
                if count[v] < need:
                    return False
                count[v] -= need
        return True

